insert into public.grammar_topics (id,level,title_tr,title_de,category,summary_tr,content_status,position) values ('grammar-a1-pronouns','A1','Ben, sen, biz: kişi zamirleri','Personalpronomen','basics','Kişiye uygun zamiri seç.','ready','1') on conflict (id) do update set level=excluded.level,title_tr=excluded.title_tr,title_de=excluded.title_de,category=excluded.category,summary_tr=excluded.summary_tr,content_status=excluded.content_status,position=excluded.position;
insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-pronouns:lesson','grammar-a1-pronouns','["Kişiye uygun zamiri seç.","sie ve Sie ayrımını bağlamla tanı."]','Kişi zamirleri bir kişi veya şeyi adını tekrar söylemeden anlatır. Türkçede özneyi düşürebiliriz; standart Almanca bildirme cümlesinde özne genellikle açıkça söylenir.','["ich = ben; du = sen; er = o (eril), sie = o (dişil), es = o (nötr).","wir = biz; ihr = siz (samimi çoğul); sie = onlar. Saygılı hitap Sie büyük harfle yazılır.","Fiil özneye göre çekilir: ich lerne, wir lernen. Cümle başındaki Sie''nin anlamı bağlamdan anlaşılır.","Zamir ismin dilbilgisel cinsiyetiyle uyumludur: das Buch → es."]','{"wrong":"Ich lernen Deutsch.","right":"Ich lerne Deutsch.","why":"ich için lerne çekimi gerekir."}','Zamirle fiili bir çift gibi öğren: ich lerne. 🌱','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-pronouns:example1','grammar-a1-pronouns:lesson','Ich lerne Deutsch.','Ben Almanca öğreniyorum.','[{"text":"Ich","role":"subject","hint":"Birinci tekil kişi."},{"text":"lerne","role":"verb","hint":"ich çekimi."},{"text":"Deutsch","role":"object","hint":"Öğrenilen dil."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-pronouns:example2','grammar-a1-pronouns:lesson','Wir wohnen in Berlin.','Biz Berlin''de yaşıyoruz.','[{"text":"Wir","role":"subject","hint":"Birinci çoğul kişi."},{"text":"wohnen","role":"verb","hint":"wir ile -en."},{"text":"in","role":"preposition","hint":"Konum bildirir."}]','2') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
