insert into public.grammar_topics (id,level,title_tr,title_de,category,summary_tr,content_status,position) values ('grammar-a1-sein-haben','A1','Olmak ve sahip olmak','Sein und haben','verbs','sein ve haben biçimlerini kişiyle eşleştir.','ready','2') on conflict (id) do update set level=excluded.level,title_tr=excluded.title_tr,title_de=excluded.title_de,category=excluded.category,summary_tr=excluded.summary_tr,content_status=excluded.content_status,position=excluded.position;
insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-sein-haben:lesson','grammar-a1-sein-haben','["sein ve haben biçimlerini kişiyle eşleştir.","Durum ve sahipliği ayırt et."]','sein durum veya kimlik, haben sahiplik ve bazı kalıp durumlar için kullanılır. Her iki fiilin çekimleri de düzenli değildir.','["sein: ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie/Sie sind.","haben: ich habe, du hast, er/sie/es hat, wir haben, ihr habt, sie/Sie haben.","Durum: Ich bin müde. Sahiplik: Ich habe ein Buch.","Yaş sein ile söylenir: Ich bin zwanzig Jahre alt. Ich habe Hunger ise yerleşik bir haben kalıbıdır."]','{"wrong":"Du habe ein Buch.","right":"Du hast ein Buch.","why":"du ile haben → hast."}','bin–bist–ist ve habe–hast–hat üçlülerini tekrar et. 🌷','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-sein-haben:example1','grammar-a1-sein-haben:lesson','Ich bin müde.','Ben yorgunum.','[{"text":"Ich","role":"subject","hint":"Birinci tekil."},{"text":"bin","role":"verb","hint":"sein fiilinin ich biçimi."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-sein-haben:example2','grammar-a1-sein-haben:lesson','Du hast ein Buch.','Senin bir kitabın var.','[{"text":"Du","role":"subject","hint":"İkinci tekil."},{"text":"hast","role":"verb","hint":"haben fiilinin du biçimi."},{"text":"ein","role":"article","hint":"Nötr akkusativ."},{"text":"Buch","role":"object","hint":"Sahip olunan nesne."}]','2') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
