insert into public.grammar_topics (id,level,title_tr,title_de,category,summary_tr,content_status,position) values ('grammar-a1-present','A1','Şimdi ve alışkanlıklar','Präsens','verbs','Präsens''in zaman bağlamlarını tanı.','ready','3') on conflict (id) do update set level=excluded.level,title_tr=excluded.title_tr,title_de=excluded.title_de,category=excluded.category,summary_tr=excluded.summary_tr,content_status=excluded.content_status,position=excluded.position;
insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-present:lesson','grammar-a1-present','["Präsens''in zaman bağlamlarını tanı.","Özneye uygun fiil biçimini seç."]','Präsens şu anı, alışkanlıkları ve zaman bağlamı belli gelecek planlarını anlatabilir. Türkçedeki -yor ve geniş zaman anlamları aynı Almanca yapıyla verilebilir.','["Düzenli fiil kök + kişi eki alır: lern-en → ich lern-e.","Temel ekler: ich -e, du -st, er/sie/es -t, wir -en, ihr -t, sie/Sie -en.","Jeden Tag alışkanlığı belirtir: Wir lernen jeden Tag.","Morgen fahre ich nach Berlin gelecek planıdır; Präsens yalnızca şu saniyeyi anlatmaz."]','{"wrong":"Ich lernt Deutsch.","right":"Ich lerne Deutsch.","why":"ich için -e gerekir."}','heute, morgen ve jeden Tag sana zamanı gösterir. ✨','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-present:example1','grammar-a1-present:lesson','Heute lerne ich Deutsch.','Bugün Almanca öğreniyorum.','[{"text":"lerne","role":"verb","hint":"Çekimli fiil ikinci öğede."},{"text":"ich","role":"subject","hint":"Özne fiilden sonra."},{"text":"Deutsch","role":"object","hint":"Öğrenilen dil."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
