insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-regular:lesson','grammar-a1-regular','["Fiil kökünü ve kişi ekini bul.","-t/-d köklerinde yardımcı e sesini tanı."]','Düzenli fiillerin kişi ekleri çoğunlukla tahmin edilebilir. Mastardaki -en bölümünü çıkar, sonra özneye uygun eki ekle.','["lernen → lern-; machen → mach-. ich lerne, du lernst, er lernt.","Çoğul çekim: wir lernen, ihr lernt, sie lernen.","arbeiten gibi -t/-d köklerinde yardımcı e görülebilir: du arbeitest, er arbeitet, ihr arbeitet.","Her fiil düzenli değildir; şablonu düzensiz fiillere zorla uygulama."]','{"wrong":"Du arbeitet heute.","right":"Du arbeitest heute.","why":"du ile arbeitest."}','Önce kök, sonra kişi: lern + st. 🌼','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
