insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-irregular:lesson','grammar-a1-irregular','["fahren, lesen ve essen değişimlerini tanı.","Tekil değişimini çoğula taşıma."]','Bazı sık fiillerde kök ünlüsü du ve er/sie/es ile değişir. Mastarla birlikte bu tekil biçimleri ayrıca öğren.','["fahren: ich fahre, du fährst, er fährt; wir fahren, ihr fahrt, sie fahren.","lesen: ich lese, du liest, er liest; wir lesen, ihr lest, sie lesen.","essen: ich esse, du isst, er isst; wir essen, ihr esst, sie essen.","Her düzensiz fiil aynı değişimi izlemez; du ve er/sie/es biçimlerini ayrıca öğren."]','{"wrong":"Du fahrst nach Berlin.","right":"Du fährst nach Berlin.","why":"du ile a → ä olur."}','fahren – du fährst – er fährt üçlüsünü birlikte ek. 🌱','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-irregular:example1','grammar-a1-irregular:lesson','Du liest ein Buch.','Sen bir kitap okuyorsun.','[{"text":"Du","role":"subject","hint":"İkinci tekil."},{"text":"liest","role":"verb","hint":"lesen → du liest."},{"text":"ein","role":"article","hint":"Buch nötrdür."},{"text":"Buch","role":"object","hint":"Okunan şey."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-irregular:example2','grammar-a1-irregular:lesson','Wir fahren nach Berlin.','Biz Berlin''e gidiyoruz.','[{"text":"Wir","role":"subject","hint":"Birinci çoğul."},{"text":"fahren","role":"verb","hint":"Çoğulda a korunur."},{"text":"nach","role":"preposition","hint":"Şehir adına yön."}]','2') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
