insert into public.grammar_topics (id,level,title_tr,title_de,category,summary_tr,content_status,position) values ('grammar-a1-articles','A1','Der, die, das: isimlerin renkleri','Bestimmte Artikel','nouns','Nominativde der, die ve das seç.','ready','6') on conflict (id) do update set level=excluded.level,title_tr=excluded.title_tr,title_de=excluded.title_de,category=excluded.category,summary_tr=excluded.summary_tr,content_status=excluded.content_status,position=excluded.position;
insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-articles:lesson','grammar-a1-articles','["Nominativde der, die ve das seç.","İsimleri artikel ve çoğuluyla öğren."]','Almanca isimlerin dilbilgisel cinsiyeti eril, dişil veya nötrdür. Bu sınıflandırma her zaman gerçek hayattaki cinsiyetle açıklanamaz. İsmi artikeliyle öğrenmek gerekir.','["Tekil nominativ: der Apfel (eril), die Blume (dişil), das Buch (nötr).","Nominativ çoğulda belirli artikel die: die Bücher. Bundan tekil cinsiyetini çıkaramazsın.","-ung ve -heit genellikle dişil, -chen küçültmeleri nötrdür: das Mädchen (kız). Doğal cinsiyet ile dilbilgisel cinsiyet aynı olmak zorunda değildir. -e sonu çoğu zaman dişildir ama der Name bir istisnadır; yeni kelimede sözlüğe bak.","İsim büyük harfle yazılır. Artikel hâle göre değişir; bu derste nominativ temelindeyiz."]','{"wrong":"Die Buch ist neu.","right":"Das Buch ist neu.","why":"Buch nötrdür: das Buch."}','Sözcüğü artikeliyle ek: das Buch. 📚','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-articles:example1','grammar-a1-articles:lesson','Der Apfel ist frisch.','Elma taze.','[{"text":"Der","role":"article","hint":"Apfel eril nominativ."},{"text":"Apfel","role":"subject","hint":"Özne."},{"text":"ist","role":"verb","hint":"sein çekimi."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
