insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-indefinite:lesson','grammar-a1-indefinite','["Nominativde ein/eine seç.","Belirsiz çoğulun artikelsizliğini fark et."]','Belirsiz artikel bir şeyi sınıfının herhangi bir üyesi olarak tanıtır. Türkçedeki “bir” yardımcı bir karşılıktır; iki dilin sistemi bire bir aynı değildir.','["Nominativ tekil: ein Mann, eine Frau, ein Kind.","Belirsiz artikelin çoğulu yoktur: ein Buch → Bücher.","Belirli şeyi kastederken der/die/das, belirsiz bir şeyi tanıtırken ein/eine kullanılabilir.","ein eril ve nötrde aynı görünür. İsmi belirli artikeliyle öğren. Akkusativ eril einen olur."]','{"wrong":"Ein Blume wächst.","right":"Eine Blume wächst.","why":"Blume dişildir; eine gerekir."}','der → ein, die → eine, das → ein. 🌷','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-indefinite:example1','grammar-a1-indefinite:lesson','Eine Blume wächst.','Bir çiçek büyüyor.','[{"text":"Eine","role":"article","hint":"Dişil nominativ belirsiz artikel."},{"text":"Blume","role":"subject","hint":"Büyüyen şey."},{"text":"wächst","role":"verb","hint":"wachsen üçüncü tekil."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
