insert into public.grammar_topics (id,level,title_tr,title_de,category,summary_tr,content_status,position) values ('grammar-a1-plurals','A1','Birden çoğa: isimlerin çoğulları','Plural der Nomen','nouns','Yaygın çoğul biçimlerini tanı.','ready','8') on conflict (id) do update set level=excluded.level,title_tr=excluded.title_tr,title_de=excluded.title_de,category=excluded.category,summary_tr=excluded.summary_tr,content_status=excluded.content_status,position=excluded.position;
insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-plurals:lesson','grammar-a1-plurals','["Yaygın çoğul biçimlerini tanı.","Umlautu ve çoğul artikelini fark et."]','Almancada bütün isimlere eklenen tek çoğul eki yoktur. Çoğulu kelimenin ayrılmaz parçası gibi öğrenmek en güvenilir yoldur.','["Sık örüntüler: -e, -(e)n, -er, -s veya ek almama. Hiçbiri tüm isimlere uygulanamaz.","der Apfel → die Äpfel; das Buch → die Bücher: bazı çoğullarda umlaut vardır.","die Blume → die Blumen; das Zimmer → die Zimmer. Nominativ çoğul belirli artikel die olur.","Sayıdan sonra çoğul genellikle gerekir: zwei Bücher. Kütle isimleri ve ölçü ifadelerinin farklı kullanımları ayrıca öğrenilir."]','{"wrong":"Zwei Buch liegen hier.","right":"Zwei Bücher liegen hier.","why":"İki kitap: zwei Bücher."}','İki biçimi birlikte ek: der Apfel – die Äpfel. 🍎','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-plurals:example1','grammar-a1-plurals:lesson','Die Bücher sind neu.','Kitaplar yeni.','[{"text":"Die","role":"article","hint":"Nominativ çoğul."},{"text":"Bücher","role":"subject","hint":"Buch''un çoğulu."},{"text":"sind","role":"verb","hint":"Çoğul özneye uygun fiil."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-plurals:example2','grammar-a1-plurals:lesson','Ich kaufe zwei Äpfel.','Ben iki elma satın alıyorum.','[{"text":"Ich","role":"subject","hint":"Özne."},{"text":"kaufe","role":"verb","hint":"ich çekimi."},{"text":"zwei Äpfel","role":"object","hint":"Sayı + çoğul isim."}]','2') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
