insert into public.grammar_topics (id,level,title_tr,title_de,category,summary_tr,content_status,position) values ('grammar-a1-negation','A1','Nicht ve kein ile olumsuzluk','Negation','sentences','İsim olumsuzluğunda kein seç.','ready','9') on conflict (id) do update set level=excluded.level,title_tr=excluded.title_tr,title_de=excluded.title_de,category=excluded.category,summary_tr=excluded.summary_tr,content_status=excluded.content_status,position=excluded.position;
insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-negation:lesson','grammar-a1-negation','["İsim olumsuzluğunda kein seç.","Sıfat olumsuzluğunda nicht kullan."]','nicht çoğunlukla bir fiili, sıfatı veya belirli öğeyi olumsuzlar. kein belirsiz artikelli veya artikelsiz bir isim grubunun olumsuz karşılığıdır.','["ein Buch → kein Buch; eine Blume → keine Blume.","Sıfat önünde nicht: Das Buch ist nicht teuer.","kein, ein gibi çekilir: Akkusativ eril einen → keinen; dişil eine → keine.","nicht''in yeri neyin olumsuzlandığına bağlıdır. Bu derste kısa, bağlamı açık isim ve sıfat örnekleriyle başlıyoruz."]','{"wrong":"Das Buch ist kein teuer.","right":"Das Buch ist nicht teuer.","why":"teuer sıfattır; nicht ile olumsuzlanır."}','Bir isme “bir tane bile yok” diyorsan çoğu zaman kein yardım eder. 🌼','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-negation:example1','grammar-a1-negation:lesson','Das Buch ist nicht teuer.','Kitap pahalı değil.','[{"text":"Das","role":"article","hint":"Buch nötrdür."},{"text":"Buch","role":"subject","hint":"Özne."},{"text":"ist","role":"verb","hint":"sein çekimi."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-negation:example2','grammar-a1-negation:lesson','Ich habe kein Buch.','Benim kitabım yok.','[{"text":"Ich","role":"subject","hint":"Özne."},{"text":"habe","role":"verb","hint":"Sahiplik fiili."},{"text":"kein","role":"article","hint":"Belirsiz isim grubunun olumsuzu."},{"text":"Buch","role":"object","hint":"Sahip olunmayan nesne."}]','2') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
