insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-word-order:lesson','grammar-a1-word-order','["Fiili bildirme cümlesinde ikinci öğeye koy.","Zaman baştayken öznenin yerini ayarla."]','Standart bildirme cümlesinde çekimli fiil ikinci öğededir. “İkinci öğe” her zaman ikinci sözcük demek değildir: çok sözcüklü bir zaman ifadesi tek öğe sayılabilir.','["Ich lerne Deutsch: özne – çekimli fiil – diğer öğeler.","Heute lerne ich Deutsch: zaman ilk öğe olur, özne fiilden sonra gelir.","Jeden Tag lerne ich Deutsch: Jeden Tag iki sözcüklü tek zaman öğesidir.","Bu kural standart bildirme cümleleri içindir. Evet/hayır soruları ve yan cümlelerin yapısı farklıdır."]','{"wrong":"Heute ich lerne Deutsch.","right":"Heute lerne ich Deutsch.","why":"Heute ilk öğedir; çekimli lerne ikinci öğeye gelir."}','İkinci sözcüğü değil, ikinci cümle öğesini düşün! ✨','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-word-order:example1','grammar-a1-word-order:lesson','Ich lerne heute Deutsch.','Ben bugün Almanca öğreniyorum.','[{"text":"Ich","role":"subject","hint":"İlk öğedeki özne."},{"text":"lerne","role":"verb","hint":"İkinci öğedeki çekimli fiil."},{"text":"Deutsch","role":"object","hint":"Öğrenilen dil."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
