insert into public.grammar_topics (id,level,title_tr,title_de,category,summary_tr,content_status,position) values ('grammar-a1-questions','A1','Soru sormanın küçük yolları','Fragen und W-Fragen','sentences','Evet/hayır ve W-sorularını ayırt et.','ready','11') on conflict (id) do update set level=excluded.level,title_tr=excluded.title_tr,title_de=excluded.title_de,category=excluded.category,summary_tr=excluded.summary_tr,content_status=excluded.content_status,position=excluded.position;
insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-questions:lesson','grammar-a1-questions','["Evet/hayır ve W-sorularını ayırt et.","wo ile wohin arasındaki farkı tanı."]','Evet/hayır sorusunda çekimli fiil başta gelir. W-sorusunda soru öğesi başta, çekimli fiil ikinci öğededir.','["Evet/hayır: Lernst du Deutsch? Önce fiil, sonra özne.","W-sorusu: Wo wohnst du? Soru öğesi + fiil + özne.","wer = kim; was = ne; wo = nerede; wohin = nereye; wann = ne zaman; warum = neden; wie = nasıl.","Wo konum, wohin yön sorar. Bağımsız sorunun sonunda soru işareti kullan."]','{"wrong":"Wo du wohnst?","right":"Wo wohnst du?","why":"Bağımsız W-sorusunda soru sözcüğünden sonra çekimli fiil gelir."}','Wo = nerede? Wohin = nereye? 🦋','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
