insert into public.grammar_topics (id,level,title_tr,title_de,category,summary_tr,content_status,position) values ('grammar-a1-accusative','A1','Akkusativ ile nesneyi bul','Akkusativ','cases','Özne ile doğrudan nesneyi ayırt et.','ready','12') on conflict (id) do update set level=excluded.level,title_tr=excluded.title_tr,title_de=excluded.title_de,category=excluded.category,summary_tr=excluded.summary_tr,content_status=excluded.content_status,position=excluded.position;
insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-accusative:lesson','grammar-a1-accusative','["Özne ile doğrudan nesneyi ayırt et.","Eril nesnede den ve einen kullan."]','Birçok fiilin doğrudan nesnesi Akkusativ alır. Özneyle nesneyi ayırmak, eril artikelin neden değiştiğini anlamanı sağlar.','["Özne nominativ: Der Mann liest. Doğrudan nesne: Ich sehe den Mann.","Akkusativ belirli artikel: der → den; die, das ve çoğul die değişmez.","Belirsiz artikel: eril ein → einen; dişil eine ve nötr ein değişmez.","Bütün fiiller aynı hâli istemez: helfen dativ ister. Yalnızca Türkçe çeviriden hâl tahmin etme."]','{"wrong":"Ich sehe der Mann.","right":"Ich sehe den Mann.","why":"Eril nesne için den gerekir."}','Eril nesne küçük bir işaret verir: der → den. 🌱','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-accusative:example1','grammar-a1-accusative:lesson','Ich sehe den Mann.','Ben adamı görüyorum.','[{"text":"Ich","role":"subject","hint":"Gören kişi."},{"text":"sehe","role":"verb","hint":"sehen Akkusativ nesne alır."},{"text":"den","role":"article","hint":"Eril akkusativ."},{"text":"Mann","role":"object","hint":"Görülen kişi."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-accusative:example2','grammar-a1-accusative:lesson','Ich lese ein Buch.','Ben bir kitap okuyorum.','[{"text":"Ich","role":"subject","hint":"Okuyan kişi."},{"text":"lese","role":"verb","hint":"lesen fiili."},{"text":"ein","role":"article","hint":"Nötr akkusativ değişmez."},{"text":"Buch","role":"object","hint":"Okunan nesne."}]','2') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
