insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-possessives:lesson','grammar-a1-possessives','["mein, dein, sein ve ihr köklerini seç.","İsme göre sahiplik ekini ayarla."]','Sahiplik artikellerinde kök sahibine göre, ek ise sahip olunan ismin cinsiyetine, sayısına ve hâline göre seçilir.','["ich → mein, du → dein, er/es → sein, sie (o) → ihr; wir → unser, ihr → euer, sie (onlar) → ihr, Sie → Ihr.","Nominativ: mein Vater, meine Mutter, mein Buch; çoğul meine Bücher.","Ali ve onun annesi: seine Mutter. Kök sahibine, -e eki Mutter ismine bağlıdır.","Akkusativ eril meinen Vater olur. euer ek aldığında çoğunlukla eure biçimine dönüşür: eure Mutter."]','{"wrong":"Mein Mutter liest.","right":"Meine Mutter liest.","why":"Mutter dişil nominativ: meine."}','Sahip kökü seçer; sahip olunan ismin yapısı eki belirler. 🌷','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-possessives:example1','grammar-a1-possessives:lesson','Meine Mutter liest.','Annem okuyor.','[{"text":"Meine","role":"article","hint":"mein + dişil nominativ -e."},{"text":"Mutter","role":"subject","hint":"Dişil tekil."},{"text":"liest","role":"verb","hint":"Üçüncü tekil çekim."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
