insert into public.grammar_topics (id,level,title_tr,title_de,category,summary_tr,content_status,position) values ('grammar-a1-modals','A1','Yapabilirim, yapmalıyım, istiyorum','Modalverben','verbs','Temel modal fiillerin anlamını ayırt et.','ready','14') on conflict (id) do update set level=excluded.level,title_tr=excluded.title_tr,title_de=excluded.title_de,category=excluded.category,summary_tr=excluded.summary_tr,content_status=excluded.content_status,position=excluded.position;
insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-modals:lesson','grammar-a1-modals','["Temel modal fiillerin anlamını ayırt et.","Modal fiille cümle çerçevesi oluştur."]','Modal fiiller yetenek, zorunluluk, izin ve istek anlamları ekler. Ana cümlede modal çekilir; diğer fiil mastar olarak sona gider.','["können = yapabilmek, müssen = zorunda olmak, dürfen = izinli olmak, wollen = istemek; sollen beklenti veya gereklilik bildirir.","können: ich kann, du kannst, er kann; wir können, ihr könnt, sie können. Tekil biçimleri ayrıca öğren.","Ich kann Deutsch lernen: çekimli kann ikinci öğede, lernen mastarı sonda.","nicht müssen = zorunda olmamak; nicht dürfen = izinli olmamak. İkisi aynı değildir."]','{"wrong":"Ich kann lerne Deutsch.","right":"Ich kann Deutsch lernen.","why":"Modal çekilir; diğer fiil mastar olarak sonda kalır."}','İki fiil bir çerçeve kursun: kann … lernen. ✨','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-modals:example1','grammar-a1-modals:lesson','Ich kann Deutsch lernen.','Ben Almanca öğrenebilirim.','[{"text":"Ich","role":"subject","hint":"Özne."},{"text":"kann","role":"verb","hint":"Çekimli modal."},{"text":"Deutsch","role":"object","hint":"Öğrenilen dil."},{"text":"lernen","role":"verb","hint":"Sondaki mastar."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-modals:example2','grammar-a1-modals:lesson','Du musst heute arbeiten.','Sen bugün çalışmak zorundasın.','[{"text":"Du","role":"subject","hint":"İkinci tekil."},{"text":"musst","role":"verb","hint":"Zorunluluk."},{"text":"arbeiten","role":"verb","hint":"Mastar sonda."}]','2') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
