insert into public.grammar_topics (id,level,title_tr,title_de,category,summary_tr,content_status,position) values ('grammar-a1-separable','A1','Ayrılan fiillerin iki parçası','Trennbare Verben','verbs','Ayrılan ön eki ana cümlede sona taşı.','ready','15') on conflict (id) do update set level=excluded.level,title_tr=excluded.title_tr,title_de=excluded.title_de,category=excluded.category,summary_tr=excluded.summary_tr,content_status=excluded.content_status,position=excluded.position;
insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-separable:lesson','grammar-a1-separable','["Ayrılan ön eki ana cümlede sona taşı.","Modal varsa mastarı bir arada tut."]','aufstehen ve einkaufen gibi fiillerin ayrılan ön eki vardır. Präsens ana cümlesinde kök çekilir; ön ek sona gider.','["aufstehen → Ich stehe um sieben Uhr auf. Çekimli kök stehe ikinci öğede, ön ek auf sonda.","einkaufen → Wir kaufen heute ein. Ön ek fiil çerçevesini kapatır.","Modal fiille mastar ayrılmaz: Ich muss früh aufstehen.","Her ön ek ayrılmaz. besuchen gibi be- ile başlayan fiilleri bu kuralla bölme; ayrılabilirliği fiille birlikte öğren."]','{"wrong":"Ich aufstehe früh.","right":"Ich stehe früh auf.","why":"Ana cümlede auf sona ayrılır."}','Ön ek kelebek gibi sona uçar. 🦋','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
