insert into public.grammar_lessons (id,topic_id,objectives,introduction_tr,rules,common_mistake,lumi_tip_tr,source_name) values ('grammar-a1-prepositions:lesson','grammar-a1-prepositions','["mit, aus, nach ve für kullanımlarını tanı.","Konum ve yön ayrımına başla."]','Edatlar bir isim grubuyla yer, yön, zaman veya ilişki bildirir. Edatın istediği hâli de öğren; Türkçedeki bir ek her zaman tek bir edata karşılık gelmez.','["mit ve aus dativ ister: mit dem Bus, aus der Türkei.","nach artikelsiz şehir ve çoğu ülke adına yön verir: nach Berlin. Artikelli ülke için in die Türkei kullanılır.","für akkusativ ister: für den Mann, für meine Schwester.","in gibi iki hâlli edatlarda konum: in der Schule; hedef: in die Schule. Yalnızca hareket var diye her zaman akkusativ seçilmez."]','{"wrong":"Ich fahre mit den Bus.","right":"Ich fahre mit dem Bus.","why":"mit dativ ister: dem Bus."}','Edatı hâliyle ek: mit + dativ, für + akkusativ. 🌼','Deutsch Garden · özgün gramer içeriği') on conflict (id) do update set topic_id=excluded.topic_id,objectives=excluded.objectives,introduction_tr=excluded.introduction_tr,rules=excluded.rules,common_mistake=excluded.common_mistake,lumi_tip_tr=excluded.lumi_tip_tr,source_name=excluded.source_name;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-prepositions:example1','grammar-a1-prepositions:lesson','Ich fahre mit dem Bus.','Ben otobüsle gidiyorum.','[{"text":"Ich","role":"subject","hint":"Özne."},{"text":"fahre","role":"verb","hint":"fahren fiili."},{"text":"mit","role":"preposition","hint":"Dativ isteyen edat."},{"text":"dem","role":"article","hint":"der Bus → dem Bus."}]','1') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
insert into public.grammar_examples (id,lesson_id,sentence_de,translation_tr,highlights,position) values ('grammar-a1-prepositions:example2','grammar-a1-prepositions:lesson','Das Buch ist für meine Schwester.','Kitap kız kardeşim için.','[{"text":"Das","role":"article","hint":"Nötr nominativ."},{"text":"Buch","role":"subject","hint":"Özne."},{"text":"ist","role":"verb","hint":"sein fiili."},{"text":"für","role":"preposition","hint":"Akkusativ isteyen edat."}]','2') on conflict (id) do update set lesson_id=excluded.lesson_id,sentence_de=excluded.sentence_de,translation_tr=excluded.translation_tr,highlights=excluded.highlights,position=excluded.position;
